using EduCenterManagement.Repositories;using EduCenterManagement.Services.Common;using EduCenterManagement.ViewModels.Timetable;namespace EduCenterManagement.Services;public sealed class TimetableService(ICurrentUserContext current,ITimetableRepository repo):ITimetableService{public async Task<TimetableViewModel?> GetWeekAsync(int userId,DateOnly start,CancellationToken ct=default){if(current.UserId!=userId||await current.GetStudentProfileIdAsync(ct) is not int student)return null;return new(){WeekStart=start,Items=await repo.GetWeekAsync(student,start,start.AddDays(6),ct)};}}
